/**
 * ============================================================
 * RevenueOS — M6.12 AI AUDIT TRAIL TEST
 * ============================================================
 *
 * This test verifies the audit trail generated by the AI worker.
 *
 * It:
 *
 * 1. Finds the latest AIDecision
 * 2. Reads all audit events for that decision
 * 3. Verifies the expected 7-event lifecycle
 * 4. Verifies event ordering
 * 5. Verifies important metadata
 * 6. Prints a complete audit summary
 *
 * IMPORTANT:
 * This test does NOT create fake customer/merchant IDs.
 * It uses a real AIDecision already created by test-ai-queue.ts.
 * ============================================================
 */

import { prisma } from "./config/database";

import {
  aiAuditService,
} from "./modules/ai/audit/audit.service";


async function main() {

  console.log("");
  console.log("============================================================");
  console.log("RevenueOS M6.12 AI AUDIT TRAIL TEST");
  console.log("============================================================");
  console.log("");


  /**
   * ==========================================================
   * STEP 1
   * FIND LATEST AI DECISION
   * ==========================================================
   */

  console.log("STEP 1 — Finding latest AIDecision...");
  console.log("");

  const decision =
    await prisma.aIDecision.findFirst({
      orderBy: {
        createdAt: "desc",
      },
    });


  if (!decision) {

    throw new Error(
      "No AIDecision found. Run test-ai-queue.ts first.",
    );

  }


  console.log("LATEST AI DECISION FOUND");
  console.log({
    decisionId: decision.decisionId,
    customerId: decision.customerId,
    merchantId: decision.merchantId,
    recoveryCaseId: decision.recoveryCaseId,
    strategy: decision.strategy,
    decisionConfidence: decision.decisionConfidence,
    probability: decision.probability,
    priorityScore: decision.priorityScore,
    createdAt: decision.createdAt,
  });


  /**
   * ==========================================================
   * STEP 2
   * READ AUDIT HISTORY
   * ==========================================================
   */

  console.log("");
  console.log("STEP 2 — Reading audit history...");
  console.log("");


  const auditHistory =
    await aiAuditService.getDecisionAudit(
      decision.decisionId,
    );


  if (!auditHistory) {

    throw new Error(
      "No audit history found for the latest AIDecision.",
    );

  }


  /**
   * ==========================================================
   * STEP 3
   * VERIFY AUDIT COUNT
   * ==========================================================
   *
   * Expected lifecycle:
   *
   * 1. AI_DECISION_STARTED
   * 2. PROBABILITY_CALCULATED
   * 3. PRIORITY_CALCULATED
   * 4. STRATEGY_RECOMMENDED
   * 5. CONFIDENCE_EVALUATED
   * 6. FALLBACK_EVALUATED
   * 7. AI_DECISION_COMPLETED
   */

  console.log(
    "AUDIT EVENTS FOUND:",
    auditHistory.length,
  );


  const expectedEventCount = 7;


  if (
    auditHistory.length !==
    expectedEventCount
  ) {

    throw new Error(
      `Expected ${expectedEventCount} audit events but found ${auditHistory.length}`,
    );

  }


  console.log(
    "✓ Audit event count is correct: 7",
  );


  /**
   * ==========================================================
   * STEP 4
   * VERIFY EVENT ORDER
   * ==========================================================
   */

  console.log("");
  console.log("STEP 4 — Verifying event order...");
  console.log("");


  const expectedEvents = [

    "AI_DECISION_STARTED",

    "PROBABILITY_CALCULATED",

    "PRIORITY_CALCULATED",

    "STRATEGY_RECOMMENDED",

    "CONFIDENCE_EVALUATED",

    "FALLBACK_EVALUATED",

    "AI_DECISION_COMPLETED",

  ];


  const actualEvents =
    auditHistory.map(
      (event: any) =>
        event.eventType,
    );


  console.log("EXPECTED EVENTS:");
  console.log(expectedEvents);

  console.log("");

  console.log("ACTUAL EVENTS:");
  console.log(actualEvents);


  for (
    let i = 0;
    i < expectedEvents.length;
    i++
  ) {

    if (
      actualEvents[i] !==
      expectedEvents[i]
    ) {

      throw new Error(
        `Audit event order mismatch at position ${i + 1}. Expected ${expectedEvents[i]}, found ${actualEvents[i]}`,
      );

    }

  }


  console.log("");
  console.log(
    "✓ Audit event order is correct",
  );


  /**
   * ==========================================================
   * STEP 5
   * VERIFY DECISION ID
   * ==========================================================
   *
   * Every audit record must belong to the
   * actual persisted AIDecision.
   */

  console.log("");
  console.log("STEP 5 — Verifying decision references...");
  console.log("");


  for (
    const event of auditHistory
  ) {

    if (
      event.decisionId !==
      decision.decisionId
    ) {

      throw new Error(
        `Invalid decisionId in audit event ${event.eventType}`,
      );

    }

  }


  console.log(
    "✓ All audit records reference the correct AIDecision",
  );


  /**
   * ==========================================================
   * STEP 6
   * VERIFY CUSTOMER / MERCHANT
   * ==========================================================
   */

  console.log("");
  console.log(
    "STEP 6 — Verifying customer and merchant references...",
  );
  console.log("");


  for (
    const event of auditHistory
  ) {

    if (
      event.customerId !==
      decision.customerId
    ) {

      throw new Error(
        `Customer mismatch in ${event.eventType}`,
      );

    }


    if (
      event.merchantId !==
      decision.merchantId
    ) {

      throw new Error(
        `Merchant mismatch in ${event.eventType}`,
      );

    }

  }


  console.log(
    "✓ Customer references are correct",
  );

  console.log(
    "✓ Merchant references are correct",
  );


  /**
   * ==========================================================
   * STEP 7
   * PRINT COMPLETE AUDIT HISTORY
   * ==========================================================
   */

  console.log("");
  console.log("============================================================");
  console.log("COMPLETE AI AUDIT HISTORY");
  console.log("============================================================");
  console.log("");


  auditHistory.forEach(
    (
      event: any,
      index: number,
    ) => {

      console.log(
        `${index + 1}. ${event.eventType}`,
      );

      console.log({
        id: event.id,
        decisionId: event.decisionId,
        merchantId: event.merchantId,
        customerId: event.customerId,
        recoveryCaseId:
          event.recoveryCaseId,

        probability:
          event.probability,

        confidence:
          event.confidence,

        priorityScore:
          event.priorityScore,

        priorityBand:
          event.priorityBand,

        strategy:
          event.strategy,

        strategyScore:
          event.strategyScore,

        confidenceBand:
          event.confidenceBand,

        fallbackRequired:
          event.fallbackRequired,

        fallbackAction:
          event.fallbackAction,

        fallbackReason:
          event.fallbackReason,

        selectedStrategy:
          event.selectedStrategy,

        decisionChanged:
          event.decisionChanged,

        modelVersion:
          event.modelVersion,

        createdAt:
          event.createdAt,

      });

      console.log("");

    },
  );


  /**
   * ==========================================================
   * STEP 8
   * FINAL SUMMARY
   * ==========================================================
   */

  console.log("");
  console.log("============================================================");
  console.log("M6.12 AUDIT TEST SUMMARY");
  console.log("============================================================");
  console.log("");

  console.log({
    decisionId:
      decision.decisionId,

    customerId:
      decision.customerId,

    merchantId:
      decision.merchantId,

    auditEventCount:
      auditHistory.length,

    expectedEventCount:
      expectedEventCount,

    events:
      actualEvents,

    finalStrategy:
      decision.strategy,

    decisionConfidence:
      decision.decisionConfidence,

    probability:
      decision.probability,

    priorityScore:
      decision.priorityScore,

  });


  console.log("");
  console.log("============================================================");
  console.log("✓ M6.12 AI AUDIT TRAIL TEST PASSED");
  console.log("============================================================");
  console.log("");

}


main()
  .catch(
    (error) => {

      console.error("");
      console.error("============================================================");
      console.error("✗ M6.12 AUDIT TEST FAILED");
      console.error("============================================================");
      console.error("");

      console.error(error);

      process.exit(1);

    },
  )
  .finally(
    async () => {

      await prisma.$disconnect();

    },
  );